CREATE TABLE "categories" ("id" TEXT NOT NULL, "parent_id" TEXT NULL REFERENCES categories (id), "name" TEXT NOT NULL, "color_value" INTEGER NOT NULL, "type" TEXT NOT NULL, "source_key" TEXT NULL, "condition_parts" TEXT NOT NULL, "position" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "copies" ("id" TEXT NOT NULL, "item_id" TEXT NOT NULL REFERENCES items (id) ON DELETE CASCADE, "edition" TEXT NULL, "price_paid_cents" INTEGER NULL, "location" TEXT NULL, "barcode" TEXT NULL, "external_edition_id" TEXT NULL, "loaned_to" TEXT NULL, "loaned_since" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "copy_conditions" ("copy_id" TEXT NOT NULL REFERENCES copies (id) ON DELETE CASCADE, "part" TEXT NOT NULL, "condition" TEXT NOT NULL, PRIMARY KEY ("copy_id", "part"));
CREATE TABLE "deck_cards" ("id" TEXT NOT NULL, "item_id" TEXT NOT NULL REFERENCES items (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "external_card_id" TEXT NULL, "quantity" INTEGER NOT NULL, "image_url" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "discovery_cache" ("id" TEXT NOT NULL, "payload" TEXT NOT NULL, "fetched_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "dismissed_suggestions" ("source_key" TEXT NOT NULL, "external_work_id" TEXT NOT NULL, PRIMARY KEY ("source_key", "external_work_id"));
CREATE TABLE "item_details" ("item_id" TEXT NOT NULL REFERENCES items (id) ON DELETE CASCADE, "payload" TEXT NOT NULL, "fetched_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("item_id"));
CREATE TABLE "item_titles" ("item_id" TEXT NOT NULL REFERENCES items (id) ON DELETE CASCADE, "language_code" TEXT NOT NULL, "title" TEXT NOT NULL, PRIMARY KEY ("item_id", "language_code"));
CREATE TABLE "items" ("id" TEXT NOT NULL, "category_id" TEXT NOT NULL REFERENCES categories (id), "series_id" TEXT NULL REFERENCES series (id), "volume_number" INTEGER NULL, "original_language" TEXT NULL, "creator" TEXT NULL, "year" INTEGER NULL, "publisher" TEXT NULL, "image_path" TEXT NULL, "spine_color_value" INTEGER NULL, "rating" INTEGER NULL, "group_key" TEXT NULL, "source_key" TEXT NULL, "external_work_id" TEXT NULL, "card_kind" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "pending_checks" ("id" TEXT NOT NULL, "kind" TEXT NOT NULL, "query" TEXT NOT NULL, "provisional_item_id" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "preferences" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "read_chapters" ("series_id" TEXT NOT NULL REFERENCES series (id) ON DELETE CASCADE, "chapter" REAL NOT NULL, PRIMARY KEY ("series_id", "chapter"));
CREATE TABLE "scan_follows" ("series_id" TEXT NOT NULL REFERENCES series (id) ON DELETE CASCADE, "site_url" TEXT NULL, "team_name" TEXT NULL, "manga_updates_series_id" TEXT NULL, "alerts_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("alerts_enabled" IN (0, 1)), "only_followed_team" INTEGER NOT NULL DEFAULT 0 CHECK ("only_followed_team" IN (0, 1)), "last_checked_at" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("series_id"));
CREATE TABLE "scan_releases" ("series_id" TEXT NOT NULL REFERENCES series (id) ON DELETE CASCADE, "chapter" REAL NOT NULL, "team_name" TEXT NOT NULL, "released_on" INTEGER NULL, "notified" INTEGER NOT NULL DEFAULT 0 CHECK ("notified" IN (0, 1)), PRIMARY KEY ("series_id", "chapter", "team_name"));
CREATE TABLE "series" ("id" TEXT NOT NULL, "category_id" TEXT NOT NULL REFERENCES categories (id), "original_language" TEXT NULL, "creator" TEXT NULL, "published_volumes" INTEGER NULL, "source_key" TEXT NULL, "external_work_id" TEXT NULL, "status" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "series_titles" ("series_id" TEXT NOT NULL REFERENCES series (id) ON DELETE CASCADE, "language_code" TEXT NOT NULL, "title" TEXT NOT NULL, PRIMARY KEY ("series_id", "language_code"));
CREATE TABLE "source_blocks" ("api_family" TEXT NOT NULL, "blocked_at" INTEGER NOT NULL, "retry_at" INTEGER NOT NULL, PRIMARY KEY ("api_family"));
CREATE TABLE "wishes" ("id" TEXT NOT NULL, "category_type" TEXT NOT NULL, "category_id" TEXT NULL REFERENCES categories (id) ON DELETE SET NULL, "title" TEXT NOT NULL, "creator" TEXT NULL, "image_url" TEXT NULL, "source_key" TEXT NULL, "external_work_id" TEXT NULL, "barcode" TEXT NULL, "series_id" TEXT NULL REFERENCES series (id) ON DELETE CASCADE, "volume_number" INTEGER NULL, "origin" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
